// Sphere tracing parameters
const int MAX_STEPS = 128;
const float EPSILON = 0.01f;
const float LIPSCHITZ = 1.5f;

// Noise parameters
const int OCTAVES = 2;
const float FREQUENCY = 0.35f;
const float AMPLITUDE = 0.5f;

float hash(ivec3 p) {
    // From https://www.shadertoy.com/view/4sfGzS
    // 3D -> 1D
    int n = p.x*3 + p.y*113 + p.z*311;
    // 1D hash by Hugo Elias
	n = (n << 13) ^ n;
    n = n * (n * n * 15731 + 789221) + 1376312589;
    return float( n & ivec3(0x0fffffff))/float(0x0fffffff);
}

float noise(in vec3 x) {
    // From https://www.shadertoy.com/view/4sfGzS
    ivec3 i = ivec3(floor(x));
    vec3 f = fract(x);
    f = f*f*(3.0-2.0*f);	
    return mix(mix(mix( hash(i+ivec3(0,0,0)), 
                        hash(i+ivec3(1,0,0)),f.x),
                   mix( hash(i+ivec3(0,1,0)), 
                        hash(i+ivec3(1,1,0)),f.x),f.y),
               mix(mix( hash(i+ivec3(0,0,1)), 
                        hash(i+ivec3(1,0,1)),f.x),
                   mix( hash(i+ivec3(0,1,1)), 
                        hash(i+ivec3(1,1,1)),f.x),f.y),f.z);
}

float fbm(in vec3 pos, int o) {
    vec3 q = pos * 12.0f;
    float f = 0.0f;
    float a = mix(0.0f, AMPLITUDE, cos(iTime * 2.0f) * 0.5 + 0.5f);
    for (int i = 0; i < o; i++) {
        f += a * noise(q);   
        q *= 2.0f;     
        a *= 0.5f;
    }
    return f;
}

float sphereNoiseSDF(vec3 p) {
    // sphere parameters
    float r = 1.0f;
    vec3 c = vec3(0.0f);

    float l = length(p - c);
    vec3 q = (r / l) * (p - c);
    float n = 0.5f * fbm(q * FREQUENCY, OCTAVES);
    r = r + n;
    return length(p - c) - r;
}

float capsuleNoiseSDF(vec3 p) {
    // capsule parameters
    vec3 a = vec3(0, -0.5, 0);
    vec3 b = vec3(0, 0.5, 0);
    float r = 0.55f;

    vec3 pa = (p - a);
    vec3 pb = (p - b);
    vec3 axis = b - a;

    // t: abscissa along segment (a, b)
    float t;
    if (dot(pa, axis) < 0.0f)
        t = 0.0f;
    else if (dot(pb, axis) > 0.0f)
        t = 1.0f;
    else
        t = dot(pa, axis) / dot(axis, axis);

    // d: Base distance to segment skeleton
    vec3 q = mix(a, b, t);
    float d = length(p - q);

    // q: point on segment surface (not skeleton!)
    q = q + (normalize(p - q) * r);

    // n: noise at point q
    float n = 0.5f * fbm(q * FREQUENCY, OCTAVES);
    r = r + n;

    // Distance minus displaced radius
    return d - r;
}

float cylinderNoiseSDF(vec3 p) {
    // (vertical) cylinder parameters
    float h = 1.0f;
    float r = 0.55f;

    vec2 qq = r / length(p.xz) * p.xz;
    vec3 qqq = vec3(qq.x, p.y, qq.y);
    float n = 0.5f * fbm(qqq * FREQUENCY, OCTAVES);
    r = r + n;

    vec2 q = abs(vec2(length(p.xz), p.y)) - vec2(r, h);
    float d = min(max(q.x, q.y), 0.0) + length(max(q, 0.0));

    return d;
}

float scene(vec3 p) {
    float ret = 10000.0f;
    ret = min(ret, sphereNoiseSDF(p - vec3(3, 0, 0)));
    ret = min(ret, cylinderNoiseSDF(p));
    ret = min(ret, capsuleNoiseSDF(p + vec3(2.5, 0, 0)));
    return ret;
}

vec3 gradient(vec3 p) {
    const float eps = 0.01f;
    float v = scene(p);
    vec3 n;
    n.x = scene(vec3(p.x + eps, p.y, p.z)) - v;
    n.y = scene(vec3(p.x, p.y + eps, p.z)) - v;
    n.z = scene(vec3(p.x, p.y, p.z + eps)) - v;
    return normalize(n);
}

bool sphereTrace(vec3 ro, vec3 rd, out float t) {
    t = 0.f;
  	for(int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * t;
        float v = scene(p);
        if (v < 0.f)
            return true;    
        t += max(EPSILON, abs(v) / LIPSCHITZ);
	}
    return false;
}

vec3 shadeBackground(vec3 rd) {
    return vec3(245.f/255.f, 245.f/255.f, 240.f/255.f);
}

vec3 shade(vec3 p, vec3 n) {
    const vec3 l1 = normalize(vec3(-2.0, -0.5, 2.5));
    const vec3 l2 = normalize(vec3(2.0, -1.1, -1.0));
    float d1 = pow(0.5 * (1.0 + dot(n, l1)), 2.5);
    float d2 = pow(0.5 * (1.0 + dot(n, l2)), 4.0);
    return vec3(0.6) + 0.25 * (d1 + d2)* shadeBackground(n);
}

vec3 rotateY(vec3 p, float a) {
    float sa = sin(a);
    float ca = cos(a);
    return vec3(ca * p.x + sa * p.z, p.y, -sa * p.x + ca * p.z);
}

mat3 setCamera(in vec3 ro, in vec3 ta, float cr ){
    vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 mo = iMouse.xy/iResolution.xy;
  	vec3 ta = vec3(0.f, 0.f, 0.f);
    float dd = 10.5f;
    vec3 ro = ta + vec3(dd*cos(7.0*mo.x), 2.2, dd*sin(7.0*mo.x) );
    mat3 ca = setCamera(ro, ta, 0.0);
    const float fl = 2.5;
    vec2 pp = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec3 rd = ca * normalize(vec3(pp, fl));

    float a = iTime * 0.25f;
    ro = rotateY(ro, a);
    rd = rotateY(rd, a);

    float t;
    bool h = sphereTrace(ro, rd, t);
    if (h) {
        vec3 p = ro + rd * t;
        vec3 n = gradient(p);
        fragColor = vec4(shade(p, n), 1.f);
    }
    else {
        fragColor = vec4(shadeBackground(rd), 1.f);
    }
}
